using Godot;
using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
namespace Arconist.GodotApp;

// Production nodes, resource and projection checks only. No GUI/input automation.
public static class GroupValidation
{
 sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
 public static async void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
  int passed=0,failed=0;var outcomes=new List<object>();var geometry=new List<object>();
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
  void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS R010 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL R010 "+name+": "+e.Message);}}
  string Load(string n)=>Godot.FileAccess.GetFileAsString("res://content/"+n);
  Kernel New(string name="native_reverse_scroll.aff"){var k=new Kernel(Chart.Parse(Load(name)));k.Frame(0);k.Frame(3002);return k;}
  void F(Kernel k,int e)=>k.Frame(e+3002);
  Test("eighteen old and grouped resources parse with their own identities",()=>{foreach(string n in new[]{"practice.aff","ordinary_two_tap.aff","mixed_practice.aff","native_hold.aff","hold_first.aff","tap_first.aff","audible_practice.aff","audible_aff120.aff","sky_practice.aff","native_moving_arc.aff","arctap_practice.aff","native_arc_tap.aff","linked_practice.aff","native_linked_arc_successors.aff","native_timing_group.aff","native_reverse_scroll.aff","native_noinput_group.aff","grouped_practice.aff"})Check(Chart.Parse(Load(n)).JudgmentUnits>0,n);});
  Test("two actual meshes distinguish groups and follow independent depths",()=>{var k=New();F(k,1100);track.Refresh(k);var a=track.TapVisual(k.Notes[0].Id)!;var b=track.TapVisual(k.Notes[1].Id)!;Check(a.Mesh is BoxMesh&&b.Mesh is BoxMesh&&!ReferenceEquals(a,b)&&a.Position==SpatialTrack.World(637,4,-3235)&&b.Position==SpatialTrack.World(-638,4,809),"native grouped positions");Check(((StandardMaterial3D)a.MaterialOverride).AlbedoColor!=((StandardMaterial3D)b.MaterialOverride).AlbedoColor,"distinguishable");});
  Test("actual meshes turn at1200 then both reach judgment line",()=>{var k=New();var depths=new List<float>();foreach(int e in new[]{1199,1200,1201,1499,1500}){F(k,e);track.Refresh(k);var b=track.TapVisual(k.Notes[1].Id)!;Check(b.Position.Z==k.Notes[1].Depth*SpatialTrack.Unit,"group depth");depths.Add(b.Position.Z);}Check(depths[0]<depths[1]&&depths[2]<depths[1]&&depths[3]>0&&depths[4]==0&&track.TapVisual(k.Notes[0].Id)!.Position.Z==0,"turn and alignment");});
  Test("positive excursion stays visible inside both perspective views",()=>{foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var k=New();foreach(int e in new[]{1000,1100,1199,1200,1201,1300,1500}){F(k,e);track.Refresh(k);var mesh=track.TapVisual(k.Notes[1].Id)!;var screen=track.Camera.UnprojectPosition(mesh.GlobalPosition);geometry.Add(new{alternate,e,depth=k.Notes[1].Depth,position=new[]{mesh.Position.X,mesh.Position.Y,mesh.Position.Z},screen=new[]{screen.X,screen.Y},visible=mesh.Visible});Check(mesh.Visible&&!track.Camera.IsPositionBehind(mesh.GlobalPosition)&&track.GetViewport().GetVisibleRect().HasPoint(screen),"frustumE"+e+" camera"+alternate);}}track.SetView(false);});
  Test("camera ray selects both actual ground lanes at shared time",()=>{foreach(bool alternate in new[]{false,true}){track.SetView(alternate);var k=New();F(k,1500);track.Refresh(k);foreach(var note in k.Notes){var screen=track.Camera.UnprojectPosition(SpatialTrack.World(SpatialTrack.NativeX(note.Lane),0,0));Check(track.Pick(screen,out var point)==note.Lane&&Math.Abs(point.Z/SpatialTrack.Unit)<0.01f,"actual ground ray");k.Down(4502,note.Lane,note.Lane);k.Up(note.Lane);}Check(k.Score==10000002,"two independent inputs");}track.SetView(false);});
  Test("actual resized viewport keeps reverse excursion and ground selection",()=>{var v=(SubViewport)track.GetViewport();var container=(SubViewportContainer)v.GetParent();var old=v.Size;bool stretch=container.Stretch;container.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)})foreach(bool alt in new[]{false,true}){v.Size=size;Check(v.Size==size,"actual size");track.SetView(alt);var k=New();F(k,1200);track.Refresh(k);var mesh=track.TapVisual(k.Notes[1].Id)!;Check(v.GetVisibleRect().HasPoint(track.Camera.UnprojectPosition(mesh.GlobalPosition)),"excursion on screen");foreach(int lane in new[]{2,5})Check(track.Pick(track.Camera.UnprojectPosition(SpatialTrack.World(SpatialTrack.NativeX(lane),0,0)),out _)==lane,"resized ground ray");}}finally{v.Size=old;container.Stretch=stretch;track.SetView(false);}});
  Test("renderer is read only for groups indexes guards and counters",()=>{var k=New();F(k,1200);string State()=>JsonSerializer.Serialize(new{k.Pure,k.Score,k.Health,k.Timeline.EffectiveTime,groups=k.TimingGroups.Select(g=>new{g.Id,g.QueryLow,g.QueryHigh,g.FrameOffset,g.Index,g.Records}),notes=k.Notes.Select(n=>new{n.Id,n.Depth,n.Active,n.Consumed,n.Missed,n.InputEnabled})});string before=State();for(int i=0;i<20;i++)track.Refresh(k);Check(before==State(),"no gameplay mutations");});
  Test("sixty second pause freezes authoritative and mesh positions",()=>{var k=New();F(k,1200);track.Refresh(k);var positions=k.Notes.Select(n=>track.TapVisual(n.Id)!.Position).ToArray();k.Pause(4202);k.Frame(64202);track.Refresh(k);Check(k.Timeline.EffectiveTime==1200&&positions.SequenceEqual(k.Notes.Select(n=>track.TapVisual(n.Id)!.Position))&&k.Pure==0,"frozen both groups");k.Resume(64202);k.Frame(64203);track.Refresh(k);Check(k.Notes[1].Depth==1209&&k.Pure==0,"advance without DOWN");});
  Test("noinput mesh remains distinct while indexed active and unjudged",()=>{var k=New("native_noinput_group.aff");F(k,1500);track.Refresh(k);var note=k.Notes[1];var mesh=track.TapVisual(note.Id)!;Check(mesh.Visible&&((StandardMaterial3D)mesh.MaterialOverride).AlbedoColor==new Color("8794b0")&&note.Active&&k.TimingGroups[1].Index[0].Contains(note.Id),"visual/index not input");k.Down(4502,42,2);k.Up(42);Check(!note.Consumed&&k.Pure==0,"no eligibility");k.Down(4502,43,5);k.Up(43);F(k,1621);Check(k.Result!.Score==10000001&&note.Active&&!note.Missed,"native completion");});
  Test("consumption hides only resolved mesh and miss uses authoritative state",()=>{var k=New();F(k,1500);track.Refresh(k);k.Down(4502,42,2);k.Up(42);track.Refresh(k);Check(!track.TapVisual(k.Notes[1].Id)!.Visible&&track.TapVisual(k.Notes[0].Id)!.Visible,"hit visibility");F(k,1601);track.Refresh(k);Check(k.Notes[0].Missed&&!track.TapVisual(k.Notes[0].Id)!.Visible&&k.Pure==1&&k.Lost==1,"miss visibility");});
  Test("extended practice results replay and menu replace group meshes",()=>{var c=new Clock();var s=new GameplaySession(c);s.Start(Load("grouped_practice.aff"));c.Milliseconds=3002;s.Frame();for(int e=1;e<=5500;e++){c.Milliseconds=e+3002;s.Frame();}track.Refresh(s.Core);var old=track.TapVisual(s.Core!.Notes[0].Id)!;s.Key('K',true);s.Key('K',false);s.Key('D',true);s.Key('D',false);c.Milliseconds=8623;s.Frame();track.Refresh(s.Core);Check(s.Core.Result!.Score==10000002&&s.Core.Chart.EndTime==5620&&s.HeldCount==0&&s.Core.Notes.All(n=>!track.TapVisual(n.Id)!.Visible),"practice results");s.Home();s.Start(Load("native_reverse_scroll.aff"));track.Refresh(s.Core);Check(!old.IsInsideTree()&&s.Core!.Pure==0&&!s.Core.Notes[1].Consumed,"fresh meshes/state");s.Home();track.Refresh(null);Check(track.TapVisual("tap:0:1500:5")==null,"menu cleanup");});
  Test("returning to old charts restores accepted camera and arc geometry",()=>{var grouped=New();track.Refresh(grouped);var old=New("native_linked_arc_successors.aff");track.Refresh(old);track.SetView(false);Check(track.Camera.Position==SpatialTrack.World(0,900,900)&&track.Camera.Far==10000*SpatialTrack.Unit&&track.ArcVisualCount==2&&old.Chart.JudgmentUnits==7,"legacy camera/linked arcs");});
  // Real Godot PCM service, no hardware audibility or latency claim.
  var bgm=new GodotBgmBackend();owner.AddChild(bgm);var clock=new Clock();var session=new GameplaySession(clock,bgm);var diagnostics=new List<BgmDiagnostic>();session.Audio!.Diagnostic+=diagnostics.Add;
  Test("production BGM strict start remains forward under reverse group",()=>{session.Start(Load("native_reverse_scroll.aff"),0,"R010-resource","res://content/audio/clockwork_steps.wav.bytes");clock.Milliseconds=3000;session.Frame();Check(!bgm.Player.Playing,"strict equality");clock.Milliseconds=3002;session.Frame();clock.Milliseconds=4202;session.Frame();Check(bgm.Player.Playing&&session.Core!.Timeline.EffectiveTime==1200&&session.Core.Notes[1].Depth==1213&&session.Audio!.Starts==1,"one forward soundtrack");});
  await owner.ToSignal(owner.GetTree().CreateTimer(0.05),SceneTreeTimer.SignalName.Timeout);
  Test("production pause seek resume preserves reverse state and new input",()=>{session.Pause();clock.Milliseconds+=60000;session.Frame();Check(session.Core!.Timeline.EffectiveTime==1200&&bgm.Player.StreamPaused,"frozen API");Check(session.Resume()&&session.Core.Pure==0&&!session.PauseModalActive,"explicit resume");Check(diagnostics.Any(d=>d.Kind=="BGM_SEEK_REQUEST"&&d.SeekMilliseconds==1200),"seek uses shared E");clock.Milliseconds=64502;session.Frame();session.Key('K',true);session.Key('K',false);session.Key('D',true);session.Key('D',false);clock.Milliseconds=64623;session.Frame();Check(session.Core.Result!.Score==10000002&&!bgm.Player.Playing&&bgm.Player.Stream==null,"results stop/unload");});
  session.Home();bgm.StopAndUnload();owner.RemoveChild(bgm);bgm.QueueFree();track.Refresh(null);track.SetView(false);
  await owner.ToSignal(owner.GetTree().CreateTimer(0.1),SceneTreeTimer.SignalName.Timeout);
  File.WriteAllText(Path.Combine(evidenceDir,"group-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,geometry,diagnostics,humanQualification="PENDING",physicalAudio="NOT RUN"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"R010 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
